package app.revanced.extension.youtube.shared;
public enum PlayerControlsVisibility{PLAYER_CONTROLS_VISIBILITY_UNKNOWN,PLAYER_CONTROLS_VISIBILITY_WILL_HIDE,PLAYER_CONTROLS_VISIBILITY_HIDDEN,PLAYER_CONTROLS_VISIBILITY_WILL_SHOW,PLAYER_CONTROLS_VISIBILITY_SHOWN;private static volatile PlayerControlsVisibility current=PLAYER_CONTROLS_VISIBILITY_UNKNOWN;private static final Event<PlayerControlsVisibility> event=new Event<>();public static PlayerControlsVisibility getCurrent(){return current;}public static void setFromString(String value){PlayerControlsVisibility next=valueOf(value);if(next!=current){current=next;event.invoke(next);}}public static Event<PlayerControlsVisibility> getOnChange(){return event;}}
